mapper.select:
SELECT id, conversation_id, participant_id, participant_type, role, 
       unread_count, join_time, last_read_time, is_deleted
FROM conversation_participant WHERE id = #{id}

mapper.update:
UPDATE conversation_participant
conversation_id = #{conversationId}, participant_id = #{participantId}, participant_type = #{participantType}, role = #{role}, unread_count = #{unreadCount}, join_time = #{joinTime}, last_read_time = #{lastReadTime}, is_deleted = #{isDeleted},
WHERE id = #{id}

mapper.select:
SELECT id, conversation_id, participant_id, participant_type, role, 
       unread_count, join_time, last_read_time, is_deleted
FROM conversation_participant 
WHERE conversation_id = #{conversationId} 
AND participant_id = #{participantId} 
AND participant_type = #{participantType}
AND is_deleted = 0

mapper.update:
UPDATE conversation_participant 
SET unread_count = unread_count + 1
WHERE conversation_id = #{conversationId} 
AND participant_type = #{participantType}
AND is_deleted = 0

UPDATE conversation_participant 
SET unread_count = 0, last_read_time = #{lastReadTime}
WHERE conversation_id = #{conversationId} 
AND participant_id = #{participantId}
AND participant_type = #{participantType}
AND is_deleted = 0
